// Three query results arrive on three inputs. Group them by shape, not by order,
// so a query returning zero rows cannot shift the sections.
const rows = $input.all().map((i) => i.json);
const newLeads = rows.filter((r) => r.n !== undefined);
const stalled = rows.filter((r) => r.last_touch_at !== undefined);
const breaches = rows.filter((r) => r.minutes_to_first_response !== undefined);

const totalNew = newLeads.reduce((s, r) => s + Number(r.n || 0), 0);
const bySource = newLeads.map((r) => '  ' + (r.source || 'unknown') + ' / ' + (r.band || 'unscored') + ': ' + r.n).join('\n');
const stalledLines = stalled.slice(0, 10).map((r) => '  ' + (r.name || r.email || r.id) + ' - last touch ' + String(r.last_touch_at).slice(0, 10)).join('\n');
const breachLines = breaches.slice(0, 10).map((r) => '  ' + (r.name || r.email || r.id) + ' - ' + Math.round(Number(r.minutes_to_first_response || 0)) + ' min').join('\n');

const text = [
  'Pipeline digest ' + new Date().toISOString().slice(0, 10),
  '',
  'New leads (24h): ' + totalNew,
  bySource || '  none',
  '',
  'Stalled (no touch in 7 days): ' + stalled.length,
  stalledLines || '  none',
  '',
  'Response-time SLA breaches (24h): ' + breaches.length,
  breachLines || '  none'
].join('\n');

return [{ json: { text, total_new: totalNew, stalled: stalled.length, breaches: breaches.length } }];
